INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt die DSGVO nur für Unternehmen in der EU?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Daten von EU-Bürgern weltweit"}, {"text": "Ja", "correct": false, "because": "Extraterritoriale Wirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die DSGVO?', 3, '[{"text": "Datenschutz stärken", "correct": true, "because": "Schützt personenbezogene Daten"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Widerspricht Minimierung"}, {"text": "Kosten senken", "correct": false, "because": "Nicht primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien legt die DSGVO fest?', 5, '[{"text": "Rechtmäßigkeit", "correct": true, "because": "Verarbeitung muss legal sein"}, {"text": "Datenminimierung", "correct": true, "because": "Nur nötige Daten erheben"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Datenschutzprinzip"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die DSGVO schützt Betroffenenrechte. b) Sie gilt nur für digitale Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch analoge Daten betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der DSGVO-Umsetzung?', 4, '[{"text": "Einwilligung der Betroffenen", "correct": false, "because": "Kern der Rechtmäßigkeit"}, {"text": "Dokumentationspflicht", "correct": false, "because": "Nachweis erforderlich"}, {"text": "Website-Design", "correct": true, "because": "Nicht datenschutzrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die DSGVO Bußgelder vorsieht?', 2, '[{"text": "Ja", "correct": true, "because": "Bis zu 20 Mio. Euro möglich"}, {"text": "Nein", "correct": false, "because": "Sanktionen sind Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflicht haben Unternehmen laut DSGVO?', 3, '[{"text": "Datenpannen melden", "correct": true, "because": "Innerhalb 72 Stunden"}, {"text": "Alle Daten speichern", "correct": false, "because": "Widerspricht Minimierung"}, {"text": "Daten verkaufen", "correct": false, "because": "Verletzt Zweckbindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte stärkt die DSGVO?', 5, '[{"text": "Auskunft", "correct": true, "because": "Betroffene können Daten einsehen"}, {"text": "Löschung", "correct": true, "because": "Recht auf Vergessenwerden"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Kein Recht"}, {"text": "Hohe Verfügbarkeit", "correct": false, "because": "Kein DSGVO-Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die DSGVO gilt für personenbezogene Daten. b) Sie ist nur für große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Verarbeiter"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die DSGVO-Umsetzung?', 4, '[{"text": "Datenschutzbeauftragter", "correct": false, "because": "Bei Bedarf Pflicht"}, {"text": "Verzeichnis von Verarbeitungstätigkeiten", "correct": false, "because": "Nachweispflicht"}, {"text": "Maximale Datensammlung", "correct": true, "because": "Widerspricht Minimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt die DSGVO nur EU-Bürger?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Daten in der EU betroffen"}, {"text": "Ja", "correct": false, "because": "Nicht nur EU-Bürger"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fordert die DSGVO?', 4, '[{"text": "Datenminimierung", "correct": true, "because": "Nur nötige Daten erheben"}, {"text": "Transparenz", "correct": true, "because": "Nutzer informieren"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Widerspricht DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die DSGVO keine Strafen hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hohe Bußgelder möglich"}, {"text": "Ja", "correct": false, "because": "Sanktionen vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der DSGVO-Umsetzung?', 3, '[{"text": "Betroffenenrechte", "correct": true, "because": "Kern der Verordnung"}, {"text": "Datenmenge erhöhen", "correct": false, "because": "Widerspricht Prinzipien"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DSGVO verlangt Dokumentation. b) Sie gilt nur für digitale Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch analoge Daten betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt die DSGVO?', 5, '[{"text": "Datenportabilität", "correct": true, "because": "Betroffenenrecht"}, {"text": "Datenschutz-Folgenabschätzung", "correct": true, "because": "Bei Risiko Pflicht"}, {"text": "Maximale Erhebung", "correct": false, "because": "Widerspricht Minimierung"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der DSGVO unwichtig?', 3, '[{"text": "Rechtsgrundlage", "correct": false, "because": "Kern der Rechtmäßigkeit"}, {"text": "Transparenz", "correct": false, "because": "Informationspflicht"}, {"text": "Farbanpassung", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt die DSGVO auch für kleine Unternehmen?', 3, '[{"text": "Ja", "correct": true, "because": "Abhängig von Datenverarbeitung"}, {"text": "Nein", "correct": false, "because": "Nicht größenabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die DSGVO technische Maßnahmen vorschreibt?', 2, '[{"text": "Ja", "correct": true, "because": "Schutzmaßnahmen erforderlich"}, {"text": "Nein", "correct": false, "because": "Teil der Anforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für DSGVO-konforme Verarbeitung?', 4, '[{"text": "Zweckbindung", "correct": true, "because": "Begrenzt Nutzung"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Maximale Datensammlung", "correct": false, "because": "Verletzt Minimierung"}]');
